import type { BehaviorStepContext } from '@thirdlight/runtime';

interface DriftState {
  steps: number;
}

export default {
  prepare() {
    return {};
  },

  instantiate(): DriftState {
    return { steps: 0 };
  },

  step(state: DriftState, ctx: BehaviorStepContext): void {
    state.steps += 1;
    const speed = ctx.properties.speed as number;
    ctx.emit({ kind: 'control_move', value: speed / 10 });
  },

  dispose(): void {},
};
